const data = $input.first().json;

const systemPrompt = `Tu es un expert en création de visuels marketing pour Ngondet Studio, basé au Gabon.

Tu reçois :
1. Une description libre du créateur
2. Un formulaire structuré partiellement rempli
3. Une image de référence (si fournie) — analyse le style, les couleurs dominantes, la composition, l'ambiance
4. La liste des templates disponibles pour ce client

Tes tâches :
- Si mode_selection = "ia" : choisir le template le plus adapté parmi templates_disponibles selon le type de visuel et la description
- Enrichir et compléter les champs manquants en te basant sur la description libre
- Si image de référence fournie : extraire le style (couleurs dominantes, ambiance, composition) et l'appliquer aux paramètres
- Optimiser les textes pour qu'ils soient percutants
- Retourner UNIQUEMENT un JSON valide, sans backticks

Format de sortie strict :
{
  "template_id": "id choisi",
  "titre_principal": "max 60 chars",
  "sous_titre": "texte ou null",
  "badge_offre": "texte ou null",
  "date_validite": "texte ou null",
  "contact_info": "texte ou null",
  "couleur_fond": "#hex",
  "logo_url": "url",
  "visuel_import_url": "url ou null",
  "style_extrait": "description du style analysé ou null"
}`;

const userText = `Mode sélection : ${data.mode_selection || 'manuel'}
Type de visuel : ${data.type_visuel || ''}
Description libre : ${data.description_libre || ''}
Titre principal : ${data.titre_principal || ''}
Sous-titre : ${data.sous_titre || ''}
Badge offre : ${data.badge_offre || ''}
Format : ${data.format || 'carré'}
Date validité : ${data.date_validite || ''}
Contact : ${data.contact_info || ''}
Couleur de fond : ${data.couleur_fond || data.couleur_principale || ''}
Note style : ${data.note_style || ''}
Logo URL : ${data.logo_url || ''}
Couleur principale : ${data.couleur_principale || ''}
Couleur secondaire : ${data.couleur_secondaire || ''}
Police : ${data.police || ''}
Image référence : ${data.image_reference_url || 'non fournie'}
Visuel import : ${data.visuel_import_url || 'non fourni'}
Template sélectionné : ${data.template_id || 'aucun — mode IA actif'}
Templates disponibles : ${JSON.stringify(data.templates_disponibles || [])}`;

const messages = [{ role: 'system', content: systemPrompt }];

if (data.image_reference_url) {
  messages.push({
    role: 'user',
    content: [
      { type: 'text', text: userText },
      { type: 'image_url', image_url: { url: data.image_reference_url } }
    ]
  });
} else {
  messages.push({ role: 'user', content: userText });
}

return [{
  json: {
    payload: {
      model: 'gpt-4o',
      messages,
      temperature: 0.7,
      max_tokens: 1000,
      response_format: { type: 'json_object' }
    },
    source: data
  }
}];

const gptData = $input.first().json;
const source = $('Construire prompt GPT').first().json.source;

let parsed;
try {
  const raw = gptData.choices[0].message.content;
  const clean = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error('Impossible de parser la réponse GPT : ' + e.message);
}

return [{
  json: {
    ...parsed,
    client_id: source.client_id,
    generation_id: source.generation_id,
    source
  }
}];

